  "faqTitle": "Fragen",
  "q1": "Wird eine Verbindung zu meiner Bank hergestellt?",
  "a1": "Nein. Future Cash verbindet sich nie mit deiner Bank und sieht weder deine Konten noch deine Umsätze. Du gibst deinen Kontostand selbst ein und aktualisierst ihn, wann immer du die neuesten Zahlen willst. Deine Rechnungen und Zahltage wiederholen sich von selbst, daher reicht meist eine kurze Aktualisierung des Kontostands.",
  "q2": "Wie halte ich alles aktuell?",
  "a2": "Öffne die App, tippe auf deinen Kontostand und gib ein, was deine Bank anzeigt. Rechnungen und Zahltage verschwinden von selbst aus der Prognose, sobald ihr Tag vorbei ist, du musst also nichts löschen. Geht etwas früher ab oder kommt später an, wische darüber, um es als bezahlt oder erhalten zu markieren.",
  "q3": "Was bedeutet „Frei verfügbar“?",
  "a3": "Das ist der höchste Betrag, den du heute ausgeben könntest, ohne dass dein Kontostand im nächsten Jahr jemals unter null fällt – mit allen Rechnungen, Gehältern und geplanten Käufen, die du hinzugefügt hast.",
  "q4": "Wo werden meine Daten gespeichert?",
  "a4": "Auf deinen Geräten und in deinem eigenen iCloud-Account, der dein iPhone, iPad und deinen Mac synchron hält. Es gibt keine Accounts, keine Server und kein Tracking. Wir können deine Daten nicht sehen.",
  "q5": "Was ist mit Steuern?",
  "a5": "Schalte bei beliebigen Einnahmen „Für Steuern zurücklegen“ ein, und Future Cash legt einen Anteil für Steuern zurück, damit dieses Geld nie als verfügbar zählt. Den Prozentsatz legst du in den Einstellungen fest.",
