  "a1": "Nem. A Future Cash soha nem kapcsolódik a bankjához, és soha nem látja a számláit vagy tranzakcióit. Az egyenlegét Ön írja be, és akkor frissíti, amikor a legfrissebb számokat szeretné látni. A számlák és a fizetések maguktól ismétlődnek, így általában elég egy gyors egyenlegfrissítés.",
