  "q1": "Si collega alla mia banca?",
  "a1": "No. Future Cash non si collega mai alla tua banca e non vede mai i tuoi conti o movimenti. Il saldo lo inserisci tu e lo aggiorni quando vuoi i dati più recenti. Bollette e stipendi si ripetono da soli, quindi di solito basta un rapido aggiornamento del saldo.",
  "q2": "Come lo tengo aggiornato?",
  "a2": "Apri l’app, tocca il saldo e scrivi quello che mostra la tua banca. Bollette e giorni di paga spariscono da soli dalla previsione una volta passato il loro giorno, quindi non devi eliminare nulla. Se qualcosa esce prima o arriva in ritardo, scorrici sopra per segnarlo come pagato o ricevuto.",
  "q3": "Cosa significa “Spendibile”?",
