  "q1": "Czy aplikacja łączy się z moim bankiem?",
  "a1": "Nie. Future Cash nigdy nie łączy się z Twoim bankiem i nie widzi Twoich kont ani transakcji. Saldo wpisujesz samodzielnie i aktualizujesz je, kiedy chcesz mieć najświeższe dane. Rachunki i wypłaty powtarzają się automatycznie, więc zwykle wystarczy szybko zaktualizować saldo.",
  "q2": "Jak dbać o aktualność danych?",
  "a2": "Otwórz aplikację, stuknij saldo i wpisz to, co pokazuje Twój bank. Rachunki i dni wypłaty same znikają z prognozy, gdy minie ich dzień, więc nie musisz niczego usuwać. Jeśli coś zejdzie wcześniej lub wpłynie później, przesuń palcem, aby oznaczyć to jako zapłacone lub otrzymane.",
  "q3": "Co oznacza „Można wydać”?",
  "a3": "To największa kwota, jaką możesz wydać dzisiaj, tak aby saldo przez następny rok nigdy nie spadło poniżej zera – z uwzględnieniem wszystkich dodanych rachunków, wypłat i planowanych zakupów.",
