  "a3": "Det är det mesta du kan spendera i dag utan att ditt saldo någonsin går under noll under det kommande året, med alla räkningar, löner och planerade köp du har lagt till.",
  "q4": "Var lagras min data?",
  "a4": "På dina enheter och i ditt eget iCloud-konto, som håller din iPhone, iPad och Mac synkade. Det finns inga konton, inga servrar och ingen spårning. Vi kan inte se din data.",
  "q5": "Hur blir det med skatten?",
  "a5": "Slå på ”Avsätt till skatt” för valfri inkomst så avsätter Future Cash en andel till skatt, och de pengarna räknas aldrig som tillgängliga. Du väljer procentsatsen i Inställningar.",
