  "feature3": "<strong>Скрізь, де ви.</strong> iPhone, iPad і Mac синхронізуються через ваш власний iCloud.",
  "affordTitle": "Чи можу я собі це дозволити?",
  "affordIntro": "Поверніть диск. Future Cash знайде перший день, коли покупка не опустить баланс нижче нуля.",
  "dialHint": "Потягніть ручку або введіть суму",
  "note": "Працює на прикладі плану з рахунками й зарплатами, починаючи з сьогодні.",
  "faqTitle": "Запитання",
  "q1": "Програма підключається до мого банку?",
  "a1": "Ні. Future Cash ніколи не підключається до банку й не бачить ваших рахунків чи операцій. Баланс ви вводите самі й оновлюєте, коли хочете мати актуальні цифри. Рахунки й зарплати повторюються автоматично, тож зазвичай достатньо швидко оновити баланс.",
  "q2": "Як підтримувати дані актуальними?",
  "a2": "Відкрийте застосунок, торкніться балансу й введіть суму, яку показує банк. Рахунки та дні зарплати самі зникають із прогнозу, щойно їхній день минув, тож нічого не потрібно видаляти. Якщо платіж пройшов раніше або надходження затрималося, проведіть по ньому, щоб позначити як сплачений чи отриманий.",
  "q3": "Що означає «Можна витратити»?",
  "a3": "Це найбільша сума, яку можна витратити сьогодні так, щоб баланс жодного разу не опустився нижче нуля протягом наступного року, з урахуванням усіх доданих рахунків, зарплат і запланованих покупок.",
  "q4": "Де зберігаються мої дані?",
