  "q1": "它会连接我的银行吗？",
  "a1": "不会。Future Cash 从不连接你的银行，也从不查看你的账户或交易。余额由你自己输入，想看最新数字时随时更新即可。账单和发薪日会自动重复，所以通常只需快速更新一下余额。",
  "q2": "如何保持数据最新？",
  "a2": "打开应用，轻点余额，输入银行显示的金额。账单和发薪日过了当天就会自动从预测中移除，无需手动删除。如果有款项提前扣除或延迟到账，轻扫即可标记为已支付或已收到。",
  "q3": "“可花金额”是什么意思？",
  "a3": "它是在计入你添加的所有账单、工资和购买计划后，你今天最多能花多少钱，同时保证未来一年余额都不会跌破零。",
  "q4": "我的数据存储在哪里？",
  "a4": "存储在你的设备和你自己的 iCloud 账户中，iCloud 会让你的 iPhone、iPad 和 Mac 保持同步。没有注册账户，没有服务器，也没有跟踪。我们看不到你的数据。",
  "q5": "税怎么办？",
  "a5": "为任意收入打开“预留税款”，Future Cash 会预留一部分用于缴税，这部分钱绝不会被算作可花的钱。你可以在“设置”中选择比例。",
