  "a1": "না। Future Cash কখনো আপনার ব্যাংকের সাথে যুক্ত হয় না এবং আপনার অ্যাকাউন্ট বা লেনদেন কখনো দেখে না। ব্যালেন্স আপনি নিজেই লেখেন, আর সর্বশেষ হিসাব চাইলে যখন খুশি আপডেট করেন। আপনার বিল ও বেতন নিজে থেকেই পুনরাবৃত্ত হয়, তাই সাধারণত ব্যালেন্সটা একটু আপডেট করলেই যথেষ্ট।",
  "q2": "কীভাবে এটি হালনাগাদ রাখব?",
  "a2": "অ্যাপটি খুলুন, আপনার ব্যালেন্সে ট্যাপ করুন এবং ব্যাংকে যা দেখাচ্ছে তা লিখুন। দিন পেরিয়ে গেলে বিল ও বেতন নিজে থেকেই পূর্বাভাস থেকে সরে যায়, তাই কিছু মুছতে হয় না। কোনোটি আগে কাটা গেলে বা দেরিতে এলে, সোয়াইপ করে পরিশোধিত বা প্রাপ্ত চিহ্নিত করুন।",
  "q3": "“নিশ্চিন্তে খরচযোগ্য” মানে কী?",
