  "faqTitle": "પ્રશ્નો",
  "q1": "શું આ મારી બૅંક સાથે જોડાય છે?",
  "a1": "ના. Future Cash ક્યારેય તમારી બૅંક સાથે જોડાતું નથી અને તમારાં ખાતાં કે વ્યવહારો ક્યારેય જોતું નથી. તમારું બૅલેન્સ તમે જાતે દાખલ કરો છો, અને જ્યારે તાજા આંકડા જોઈએ ત્યારે તેને અપડેટ કરો છો. તમારાં બિલ અને પગાર આપમેળે પુનરાવર્તિત થાય છે, તેથી સામાન્ય રીતે ઝડપથી બૅલેન્સ અપડેટ કરવું જ પૂરતું છે.",
  "q2": "તેને અપ ટુ ડેટ કેવી રીતે રાખું?",
  "a2": "ઍપ ખોલો, તમારા બૅલેન્સ પર ટૅપ કરો અને તમારી બૅંક જે બતાવે છે તે ટાઇપ કરો. બિલ અને પગારનો દિવસ પસાર થઈ જાય એટલે તે આપમેળે અનુમાનમાંથી નીકળી જાય છે, તેથી કંઈ ડિલીટ કરવાની જરૂર નથી. જો કોઈ ચુકવણી વહેલી થાય કે મોડી આવે, તો તેને ચૂકવેલી કે મળેલી માર્ક કરવા સ્વાઇપ કરો.",
  "q3": "“ખર્ચ માટે સુરક્ષિત”નો અર્થ શું છે?",
  "a3": "આ એ મહત્તમ રકમ છે જે તમે આજે ખર્ચી શકો અને છતાં આવતા એક વર્ષમાં તમારું બૅલેન્સ ક્યારેય શૂન્યથી નીચે ન જાય, તમે ઉમેરેલાં બધાં બિલ, પગાર અને આયોજિત ખરીદીઓ ગણીને.",
  "q4": "મારો ડેટા ક્યાં સંગ્રહાય છે?",
  "a4": "તમારાં ડિવાઇસ પર અને તમારા પોતાના iCloud એકાઉન્ટમાં, જે તમારા iPhone, iPad અને Macને સિંકમાં રાખે છે. કોઈ એકાઉન્ટ નહીં, કોઈ સર્વર નહીં અને કોઈ ટ્રૅકિંગ નહીં. અમે તમારો ડેટા જોઈ શકતા નથી.",
