  "feature3": "<strong>ನೀವು ಎಲ್ಲಿದ್ದರೂ.",
  "affordTitle": "ನನಗೆ ಇದು ಸಾಧ್ಯವೇ?",
  "affordIntro": "ಡಯಲ್ ತಿರುಗಿಸಿ. ಎಂದಿಗೂ ಸೊನ್ನೆಗಿಂತ ಕೆಳಗೆ ಹೋಗದೆ ಅದನ್ನು ಕೊಳ್ಳಬಹುದಾದ ಮೊದಲ ದಿನವನ್ನು Future Cash ಹುಡುಕುತ್ತದೆ.",
  "dialHint": "ನಾಬ್ ಎಳೆಯಿರಿ ಅಥವಾ ಟೈಪ್ ಮಾಡಿ",
  "note": "ಇಂದಿನಿಂದ ಆರಂಭವಾಗುವ ಬಿಲ್‌ಗಳು ಮತ್ತು ಸಂಬಳದ ದಿನಗಳ ಉದಾಹರಣೆ ಯೋಜನೆಯಲ್ಲಿ ನಡೆಯುತ್ತದೆ.",
  "faqTitle": "ಪ್ರಶ್ನೆಗಳು",
  "q1": "ಇದು ನನ್ನ ಬ್ಯಾಂಕ್‌ಗೆ ಸಂಪರ್ಕಿಸುತ್ತದೆಯೇ?",
  "a1": "ಇಲ್ಲ. Future Cash ಎಂದಿಗೂ ನಿಮ್ಮ ಬ್ಯಾಂಕ್‌ಗೆ ಸಂಪರ್ಕಿಸುವುದಿಲ್ಲ, ನಿಮ್ಮ ಖಾತೆಗಳನ್ನು ಅಥವಾ ವಹಿವಾಟುಗಳನ್ನು ನೋಡುವುದಿಲ್ಲ. ನಿಮ್ಮ ಬ್ಯಾಲೆನ್ಸ್ ಅನ್ನು ನೀವೇ ಟೈಪ್ ಮಾಡುತ್ತೀರಿ, ಹೊಸ ಅಂಕಿಗಳು ಬೇಕಾದಾಗ ಅಪ್‌ಡೇಟ್ ಮಾಡುತ್ತೀರಿ. ನಿಮ್ಮ ಬಿಲ್‌ಗಳು ಮತ್ತು ಸಂಬಳದ ದಿನಗಳು ತಾನಾಗಿಯೇ ಪುನರಾವರ್ತನೆಯಾಗುತ್ತವೆ, ಹಾಗಾಗಿ ಸಾಮಾನ್ಯವಾಗಿ ಒಂದು ಸಣ್ಣ ಬ್ಯಾಲೆನ್ಸ್ ಅಪ್‌ಡೇಟ್ ಸಾಕು.",
  "q2": "ಇದನ್ನು ಅಪ್‌ಡೇಟ್ ಆಗಿ ಇಡುವುದು ಹೇಗೆ?",
  "a2": "ಆ್ಯಪ್ ತೆರೆಯಿರಿ, ನಿಮ್ಮ ಬ್ಯಾಲೆನ್ಸ್ ಮೇಲೆ ಟ್ಯಾಪ್ ಮಾಡಿ, ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ತೋರಿಸುವ ಮೊತ್ತವನ್ನು ಟೈಪ್ ಮಾಡಿ. ಬಿಲ್‌ಗಳು ಮತ್ತು ಸಂಬಳದ ದಿನಗಳು ಅವುಗಳ ದಿನ ಕಳೆದ ಮೇಲೆ ತಾನಾಗಿಯೇ ಮುನ್ಸೂಚನೆಯಿಂದ ಹೊರಗೆ ಹೋಗುತ್ತವೆ, ಹಾಗಾಗಿ ಏನನ್ನೂ ಅಳಿಸಬೇಕಿಲ್ಲ. ಯಾವುದಾದರೂ ಬೇಗ ಹೋದರೆ ಅಥವಾ ತಡವಾಗಿ ಬಂದರೆ, ಅದನ್ನು ಸ್ವೈಪ್ ಮಾಡಿ ಪಾವತಿಸಲಾಗಿದೆ ಅಥವಾ ಸ್ವೀಕರಿಸಲಾಗಿದೆ ಎಂದು ಗುರುತಿಸಿ.",
  "q3": "“ಖರ್ಚಿಗೆ ಲಭ್ಯ” ಎಂದರೆ ಏನು?",
  "a3": "ನೀವು ಸೇರಿಸಿದ ಪ್ರತಿ ಬಿಲ್, ಸಂಬಳ ಮತ್ತು ಯೋಜಿತ ಖರೀದಿಯನ್ನು ಲೆಕ್ಕಕ್ಕೆ ತೆಗೆದುಕೊಂಡು, ಮುಂದಿನ ಒಂದು ವರ್ಷದಲ್ಲಿ ನಿಮ್ಮ ಬ್ಯಾಲೆನ್ಸ್ ಎಂದಿಗೂ ಸೊನ್ನೆಗಿಂತ ಕೆಳಗೆ ಹೋಗದಂತೆ ಇಂದು ನೀವು ಖರ್ಚು ಮಾಡಬಹುದಾದ ಗರಿಷ್ಠ ಮೊತ್ತ ಇದು.",
  "q4": "ನನ್ನ ಡೇಟಾ ಎಲ್ಲಿ ಸಂಗ್ರಹವಾಗುತ್ತದೆ?",
  "a4": "ನಿಮ್ಮ ಸಾಧನಗಳಲ್ಲಿ ಮತ್ತು ನಿಮ್ಮದೇ iCloud ಖಾತೆಯಲ್ಲಿ, ಅದು ನಿಮ್ಮ iPhone, iPad ಮತ್ತು Mac ಅನ್ನು ಸಿಂಕ್‌ನಲ್ಲಿ ಇಡುತ್ತದೆ. ಯಾವುದೇ ಖಾತೆಗಳಿಲ್ಲ, ಸರ್ವರ್‌ಗಳಿಲ್ಲ, ಟ್ರ್ಯಾಕಿಂಗ್ ಇಲ್ಲ. ನಿಮ್ಮ ಡೇಟಾ ನಮಗೆ ಕಾಣುವುದಿಲ್ಲ.",
  "q5": "ತೆರಿಗೆಗಳ ಬಗ್ಗೆ ಏನು?",
  "a5": "ಯಾವುದೇ ಆದಾಯಕ್ಕೆ “ತೆರಿಗೆಗಾಗಿ ಮೀಸಲಿಡಿ” ಆನ್ ಮಾಡಿ, Future Cash ತೆರಿಗೆಗಾಗಿ ಒಂದು ಪಾಲನ್ನು ಮೀಸಲಿಡುತ್ತದೆ, ಹಾಗಾಗಿ ಆ ಹಣವನ್ನು ಎಂದಿಗೂ ಖರ್ಚಿನ ಹಣವೆಂದು ಎಣಿಸುವುದಿಲ್ಲ. ಶೇಕಡಾವಾರನ್ನು ನೀವು ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಆಯ್ಕೆಮಾಡುತ್ತೀರಿ.",
