  "a1": "ഇല്ല. Future Cash ഒരിക്കലും നിങ്ങളുടെ ബാങ്കുമായി ബന്ധിപ്പിക്കുന്നില്ല, നിങ്ങളുടെ അക്കൗണ്ടുകളോ ഇടപാടുകളോ കാണുന്നുമില്ല. ബാലൻസ് നിങ്ങൾ തന്നെ ടൈപ്പ് ചെയ്യുന്നു, പുതിയ കണക്കുകൾ വേണ്ടപ്പോഴെല്ലാം അത് പുതുക്കാം. ബില്ലുകളും ശമ്പള ദിവസങ്ങളും സ്വയം ആവർത്തിക്കുന്നതിനാൽ, സാധാരണയായി ഒരു ചെറിയ ബാലൻസ് അപ്‌ഡേറ്റ് മതിയാകും.",
  "q2": "ഇത് എങ്ങനെ കാലികമായി നിലനിർത്താം?",
  "a2": "ആപ്പ് തുറന്ന് ബാലൻസിൽ ടാപ്പ് ചെയ്ത് നിങ്ങളുടെ ബാങ്ക് കാണിക്കുന്ന തുക ടൈപ്പ് ചെയ്യൂ. ബില്ലുകളും ശമ്പള ദിവസങ്ങളും അവയുടെ ദിവസം കഴിഞ്ഞാൽ പ്രവചനത്തിൽ നിന്ന് സ്വയം മാറും, അതിനാൽ ഒന്നും ഇല്ലാതാക്കേണ്ടതില്ല. ഏതെങ്കിലും നേരത്തേ പോകുകയോ വൈകി വരികയോ ചെയ്താൽ, അടച്ചതായോ ലഭിച്ചതായോ അടയാളപ്പെടുത്താൻ അതിൽ സ്വൈപ്പ് ചെയ്യൂ.",
  "q3": "“ചെലവാക്കാവുന്നത്” എന്നതിന്റെ അർത്ഥമെന്താണ്?",
  "a3": "നിങ്ങൾ ചേർത്ത എല്ലാ ബില്ലുകളും ശമ്പളവും പ്ലാൻ ചെയ്ത വാങ്ങലുകളും കണക്കിലെടുത്ത്, അടുത്ത ഒരു വർഷത്തിനുള്ളിൽ ബാലൻസ് ഒരിക്കലും പൂജ്യത്തിന് താഴെ പോകാതെ ഇന്ന് ചെലവാക്കാവുന്ന പരമാവധി തുകയാണിത്.",
  "q4": "എന്റെ ഡാറ്റ എവിടെയാണ് സൂക്ഷിക്കുന്നത്?",
  "a4": "നിങ്ങളുടെ ഉപകരണങ്ങളിലും നിങ്ങളുടെ സ്വന്തം iCloud അക്കൗണ്ടിലും. അതാണ് നിങ്ങളുടെ iPhone, iPad, Mac എന്നിവ സമന്വയത്തിൽ നിലനിർത്തുന്നത്. അക്കൗണ്ടുകളില്ല, സെർവറുകളില്ല, ട്രാക്കിംഗില്ല. ഞങ്ങൾക്ക് നിങ്ങളുടെ ഡാറ്റ കാണാനാകില്ല.",
  "q5": "നികുതിയുടെ കാര്യമോ?",
  "a5": "ഏത് വരുമാനത്തിനും “നികുതിക്കായി മാറ്റിവെക്കുക” ഓണാക്കൂ, Future Cash ഒരു വിഹിതം നികുതിക്കായി മാറ്റിവെക്കും, അതിനാൽ ആ പണം ഒരിക്കലും ചെലവാക്കാവുന്നതായി കണക്കാക്കില്ല. ശതമാനം ക്രമീകരണങ്ങളിൽ നിങ്ങൾക്ക് തിരഞ്ഞെടുക്കാം.",
