  "note": "ଆଜିଠାରୁ ଆରମ୍ଭ ହେଉଥିବା ବିଲ୍ ଓ ଦରମା ଦିନର ଏକ ଉଦାହରଣ ଯୋଜନାରେ ଚାଲେ।",
  "faqTitle": "ପ୍ରଶ୍ନ",
  "q1": "ଏହା ମୋ ବ୍ୟାଙ୍କ ସହ ଯୋଡ଼ି ହୁଏ କି?",
  "a1": "ନା। Future Cash କେବେ ଆପଣଙ୍କ ବ୍ୟାଙ୍କ ସହ ଯୋଡ଼ି ହୁଏ ନାହିଁ ଏବଂ ଆପଣଙ୍କ ଆକାଉଣ୍ଟ କିମ୍ବା ଟ୍ରାଞ୍ଜାକସନ୍ କେବେ ଦେଖେ ନାହିଁ। ଆପଣ ନିଜେ ଆପଣଙ୍କ ବାଲାନ୍ସ ଲେଖନ୍ତି, ଏବଂ ସର୍ବଶେଷ ହିସାବ ଚାହିଁଲେ ଯେକୌଣସି ସମୟରେ ଅପଡେଟ୍ କରନ୍ତି। ଆପଣଙ୍କ ବିଲ୍ ଓ ଦରମା ଦିନ ନିଜେ ପୁନରାବୃତ୍ତି ହୁଏ, ତେଣୁ ସାଧାରଣତଃ ଟିକେ ବାଲାନ୍ସ ଅପଡେଟ୍ ହିଁ ଯଥେଷ୍ଟ।",
  "q2": "ମୁଁ ଏହାକୁ କିପରି ଅପ-ଟୁ-ଡେଟ୍ ରଖିବି?",
  "a2": "ଆପ୍ ଖୋଲନ୍ତୁ, ଆପଣଙ୍କ ବାଲାନ୍ସରେ ଟାପ୍ କରନ୍ତୁ ଏବଂ ଆପଣଙ୍କ ବ୍ୟାଙ୍କ ଯାହା ଦେଖାଉଛି ତାହା ଲେଖନ୍ତୁ। ବିଲ୍ ଓ ଦରମା ଦିନ ସେମାନଙ୍କ ଦିନ ବିତିଗଲେ ନିଜେ ପୂର୍ବାନୁମାନରୁ ହଟିଯାଏ, ତେଣୁ କିଛି ଡିଲିଟ୍ କରିବାକୁ ପଡ଼େ ନାହିଁ। କୌଣସିଟି ଆଗରୁ କଟିଗଲେ କିମ୍ବା ଡେରିରେ ଆସିଲେ, ପୈଠ କିମ୍ବା ମିଳିଛି ବୋଲି ଚିହ୍ନିତ କରିବାକୁ ସ୍ୱାଇପ୍ କରନ୍ତୁ।",
  "q3": "“ଖର୍ଚ୍ଚ କରିପାରିବେ” ର ଅର୍ଥ କ’ଣ?",
  "a3": "ଆପଣ ଯୋଡ଼ିଥିବା ପ୍ରତ୍ୟେକ ବିଲ୍, ଦରମା ଓ ଯୋଜନା କରିଥିବା କ୍ରୟକୁ ଗଣି, ଆଗାମୀ ଏକ ବର୍ଷରେ ବାଲାନ୍ସ କେବେ ଶୂନ୍ୟରୁ ତଳକୁ ନ ଯାଇ ଆପଣ ଆଜି ସର୍ବାଧିକ ଯେତିକି ଖର୍ଚ୍ଚ କରିପାରିବେ।",
  "q4": "ମୋ ଡାଟା କେଉଁଠି ରଖାଯାଏ?",
  "a4": "ଆପଣଙ୍କ ଡିଭାଇସରେ ଏବଂ ଆପଣଙ୍କ ନିଜ iCloud ଆକାଉଣ୍ଟରେ, ଯାହା ଆପଣଙ୍କ iPhone, iPad ଓ Macକୁ ସିଙ୍କରେ ରଖେ। କୌଣସି ଆକାଉଣ୍ଟ ନାହିଁ, ସର୍ଭର ନାହିଁ, ଟ୍ରାକିଂ ନାହିଁ। ଆମେ ଆପଣଙ୍କ ଡାଟା ଦେଖିପାରୁ ନାହିଁ।",
  "q5": "ଟିକସ ବିଷୟରେ କ’ଣ?",
  "a5": "ଯେକୌଣସି ଆୟ ପାଇଁ “ଟିକସ ପାଇଁ ଅଲଗା ରଖନ୍ତୁ” ଚାଲୁ କରନ୍ତୁ, ଆଉ Future Cash ଟିକସ ପାଇଁ ଏକ ଅଂଶ ଅଲଗା ରଖିବ, ଯାହାଫଳରେ ସେହି ଟଙ୍କା କେବେ ଖର୍ଚ୍ଚଯୋଗ୍ୟ ଭାବେ ଗଣାଯିବ ନାହିଁ। ସେଟିଂସରେ ଆପଣ ପ୍ରତିଶତ ବାଛନ୍ତୁ।",
