  "q1": "ਕੀ ਇਹ ਮੇਰੇ ਬੈਂਕ ਨਾਲ ਜੁੜਦਾ ਹੈ?",
  "a1": "ਨਹੀਂ। Future Cash ਕਦੇ ਵੀ ਤੁਹਾਡੇ ਬੈਂਕ ਨਾਲ ਨਹੀਂ ਜੁੜਦਾ ਅਤੇ ਤੁਹਾਡੇ ਖਾਤੇ ਜਾਂ ਲੈਣ-ਦੇਣ ਕਦੇ ਨਹੀਂ ਦੇਖਦਾ। ਤੁਸੀਂ ਆਪਣਾ ਬੈਲੇਂਸ ਖ਼ੁਦ ਭਰਦੇ ਹੋ, ਅਤੇ ਜਦੋਂ ਵੀ ਤਾਜ਼ਾ ਅੰਕੜੇ ਚਾਹੀਦੇ ਹੋਣ ਇਸਨੂੰ ਅੱਪਡੇਟ ਕਰ ਲੈਂਦੇ ਹੋ। ਤੁਹਾਡੇ ਬਿੱਲ ਅਤੇ ਤਨਖ਼ਾਹਾਂ ਆਪਣੇ-ਆਪ ਦੁਹਰਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਇਸ ਲਈ ਆਮ ਤੌਰ ’ਤੇ ਬੈਲੇਂਸ ਦਾ ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਅੱਪਡੇਟ ਹੀ ਕਾਫ਼ੀ ਹੁੰਦਾ ਹੈ।",
  "q2": "ਮੈਂ ਇਸਨੂੰ ਅੱਪ-ਟੂ-ਡੇਟ ਕਿਵੇਂ ਰੱਖਾਂ?",
  "a2": "ਐਪ ਖੋਲ੍ਹੋ, ਆਪਣੇ ਬੈਲੇਂਸ ’ਤੇ ਟੈਪ ਕਰੋ ਅਤੇ ਉਹ ਰਕਮ ਲਿਖੋ ਜੋ ਤੁਹਾਡਾ ਬੈਂਕ ਦਿਖਾਉਂਦਾ ਹੈ। ਬਿੱਲ ਅਤੇ ਤਨਖ਼ਾਹਾਂ ਆਪਣਾ ਦਿਨ ਲੰਘਣ ’ਤੇ ਅਨੁਮਾਨ ਵਿੱਚੋਂ ਆਪਣੇ-ਆਪ ਹਟ ਜਾਂਦੀਆਂ ਹਨ, ਇਸ ਲਈ ਕੁਝ ਵੀ ਮਿਟਾਉਣ ਦੀ ਲੋੜ ਨਹੀਂ। ਜੇ ਕੋਈ ਭੁਗਤਾਨ ਪਹਿਲਾਂ ਹੋ ਜਾਵੇ ਜਾਂ ਦੇਰ ਨਾਲ ਆਵੇ, ਤਾਂ ਉਸਨੂੰ ਸਵਾਈਪ ਕਰਕੇ ਭੁਗਤਾਨ ਹੋਇਆ ਜਾਂ ਮਿਲ ਗਿਆ ਮਾਰਕ ਕਰੋ।",
  "q3": "“ਖ਼ਰਚਣ ਲਈ ਸੁਰੱਖਿਅਤ” ਦਾ ਕੀ ਮਤਲਬ ਹੈ?",
  "a3": "ਇਹ ਉਹ ਵੱਧ ਤੋਂ ਵੱਧ ਰਕਮ ਹੈ ਜੋ ਤੁਸੀਂ ਅੱਜ ਖ਼ਰਚ ਸਕਦੇ ਹੋ, ਬਿਨਾਂ ਅਗਲੇ ਇੱਕ ਸਾਲ ਵਿੱਚ ਤੁਹਾਡਾ ਬੈਲੇਂਸ ਕਦੇ ਜ਼ੀਰੋ ਤੋਂ ਹੇਠਾਂ ਗਏ, ਤੁਹਾਡੇ ਜੋੜੇ ਹਰ ਬਿੱਲ, ਤਨਖ਼ਾਹ ਅਤੇ ਯੋਜਨਾਬੱਧ ਖ਼ਰੀਦ ਨੂੰ ਗਿਣ ਕੇ।",
  "q4": "ਮੇਰਾ ਡਾਟਾ ਕਿੱਥੇ ਸਟੋਰ ਹੁੰਦਾ ਹੈ?",
  "a4": "ਤੁਹਾਡੇ ਡਿਵਾਈਸਾਂ ’ਤੇ ਅਤੇ ਤੁਹਾਡੇ ਆਪਣੇ iCloud ਖਾਤੇ ਵਿੱਚ, ਜੋ ਤੁਹਾਡੇ iPhone, iPad ਅਤੇ Mac ਨੂੰ ਸਿੰਕ ਵਿੱਚ ਰੱਖਦਾ ਹੈ। ਨਾ ਕੋਈ ਖਾਤਾ, ਨਾ ਸਰਵਰ, ਨਾ ਟਰੈਕਿੰਗ। ਅਸੀਂ ਤੁਹਾਡਾ ਡਾਟਾ ਨਹੀਂ ਦੇਖ ਸਕਦੇ।",
  "q5": "ਟੈਕਸ ਦਾ ਕੀ?",
  "a5": "ਕਿਸੇ ਵੀ ਆਮਦਨ ਲਈ “ਟੈਕਸ ਲਈ ਵੱਖਰਾ ਰੱਖੋ” ਚਾਲੂ ਕਰੋ ਅਤੇ Future Cash ਟੈਕਸ ਲਈ ਇੱਕ ਹਿੱਸਾ ਵੱਖਰਾ ਰੱਖ ਦਿੰਦਾ ਹੈ, ਤਾਂ ਜੋ ਉਹ ਪੈਸੇ ਕਦੇ ਖ਼ਰਚਣਯੋਗ ਨਾ ਗਿਣੇ ਜਾਣ। ਪ੍ਰਤੀਸ਼ਤ ਤੁਸੀਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਚੁਣਦੇ ਹੋ।",
