  "ariaTimeline": "ਭੁਗਤਾਨਾਂ ਦੀ ਟਾਈਮਲਾਈਨ, ਹਰੇਕ ਤੋਂ ਬਾਅਦ ਦੇ ਬੈਲੇਂਸ ਸਮੇਤ, ਨਾਲ ਹੀ ਲਿਸਬਨ ਦੀ ਯਾਤਰਾ ਦਰਸਾਈ ਹੋਈ",
