  "affordIntro": "டயலைச் சுழற்றுங்கள். பூஜ்ஜியத்துக்குக் கீழே ஒருபோதும் போகாமல் அதை வாங்கக்கூடிய முதல் நாளை Future Cash கண்டுபிடிக்கும்.",
