  "note": "இன்று முதல் தொடங்கும், பில்களும் சம்பள நாட்களும் கொண்ட ஒரு மாதிரித் திட்டத்தில் இயங்குகிறது.",
  "faqTitle": "கேள்விகள்",
  "q1": "இது என் வங்கியுடன் இணையுமா?",
  "a1": "இல்லை. Future Cash உங்கள் வங்கியுடன் ஒருபோதும் இணையாது, உங்கள் கணக்குகளையோ பரிவர்த்தனைகளையோ பார்க்காது. உங்கள் இருப்பை நீங்களே உள்ளிடுகிறீர்கள், சமீபத்திய தொகை வேண்டும்போதெல்லாம் புதுப்பிக்கலாம். உங்கள் பில்களும் சம்பள நாட்களும் தானாகவே மீண்டும் வரும், அதனால் பொதுவாக ஒரு சிறு இருப்புப் புதுப்பிப்பே போதும்.",
  "q2": "இதை எப்படிப் புதுப்பித்த நிலையில் வைத்திருப்பது?",
  "a2": "ஆப்பைத் திறந்து, உங்கள் இருப்பைத் தட்டி, உங்கள் வங்கி காட்டும் தொகையை உள்ளிடுங்கள். பில்களும் சம்பள நாட்களும் அவற்றின் நாள் கடந்ததும் தானாகவே முன்கணிப்பிலிருந்து விலகிவிடும், அதனால் எதையும் நீக்கத் தேவையில்லை. ஏதாவது முன்கூட்டியே போனாலோ தாமதமாக வந்தாலோ, அதை ஸ்வைப் செய்து செலுத்தியதாக அல்லது பெற்றதாகக் குறியுங்கள்.",
  "q3": "“செலவிடக்கூடியது” என்றால் என்ன?",
  "a3": "நீங்கள் சேர்த்த ஒவ்வொரு பில், சம்பளம், திட்டமிட்ட கொள்முதல் அனைத்தையும் கணக்கில் கொண்டு, அடுத்த ஓராண்டில் உங்கள் இருப்பு ஒருபோதும் பூஜ்ஜியத்துக்குக் கீழே போகாமல் இன்று நீங்கள் செலவிடக்கூடிய அதிகபட்சத் தொகை இது.",
  "q4": "என் தரவு எங்கே சேமிக்கப்படுகிறது?",
  "a4": "உங்கள் சாதனங்களிலும் உங்கள் சொந்த iCloud கணக்கிலும். அதுவே உங்கள் iPhone, iPad, Mac-ஐ ஒத்திசைவில் வைத்திருக்கிறது. கணக்குகள் இல்லை, சர்வர்கள் இல்லை, கண்காணிப்பு இல்லை. உங்கள் தரவை எங்களால் பார்க்க முடியாது.",
  "q5": "வரி எப்படி?",
  "a5": "எந்த வருமானத்துக்கும் “வரிக்காக ஒதுக்கியது” என்பதை இயக்குங்கள், Future Cash ஒரு பங்கை வரிக்காக ஒதுக்கும், அதனால் அந்தப் பணம் ஒருபோதும் செலவிடக்கூடியதாகக் கணக்கிடப்படாது. சதவீதத்தை அமைப்புகளில் நீங்களே தேர்ந்தெடுக்கலாம்.",
