  "affordIntro": "డయల్ తిప్పండి. బ్యాలెన్స్ ఎప్పుడూ సున్నా కంటే తగ్గకుండా మీరు దాన్ని కొనగలిగే మొదటి రోజును Future Cash కనుగొంటుంది.",
  "dialHint": "నాబ్‌ను డ్రాగ్ చేయండి లేదా టైప్ చేయండి",
