  "faqTitle": "ప్రశ్నలు",
  "q1": "ఇది నా బ్యాంక్‌కు కనెక్ట్ అవుతుందా?",
  "a1": "లేదు. Future Cash ఎప్పుడూ మీ బ్యాంక్‌కు కనెక్ట్ అవ్వదు, మీ ఖాతాలను లేదా లావాదేవీలను ఎప్పుడూ చూడదు. మీ బ్యాలెన్స్‌ను మీరే టైప్ చేస్తారు, తాజా అంకెలు కావాలనుకున్నప్పుడల్లా అప్‌డేట్ చేస్తారు. మీ బిల్లులు, జీతం రోజులు వాటంతట అవే పునరావృతమవుతాయి, కాబట్టి సాధారణంగా ఒక చిన్న బ్యాలెన్స్ అప్‌డేట్ సరిపోతుంది.",
  "q2": "దీన్ని ఎలా అప్‌డేట్‌గా ఉంచాలి?",
  "a2": "యాప్ తెరిచి, మీ బ్యాలెన్స్‌ను ట్యాప్ చేసి, మీ బ్యాంక్ చూపించే మొత్తాన్ని టైప్ చేయండి. బిల్లులు, జీతం రోజులు వాటి రోజు దాటిన తర్వాత అంచనా నుండి వాటంతట అవే తొలగిపోతాయి, కాబట్టి ఏమీ తొలగించాల్సిన అవసరం లేదు. ఏదైనా ముందే వెళ్లినా లేదా ఆలస్యంగా వచ్చినా, దాన్ని స్వైప్ చేసి చెల్లించినట్లు లేదా అందినట్లు గుర్తించండి.",
  "q3": "“ఖర్చు చేయగలిగేది” అంటే ఏమిటి?",
  "a3": "మీరు జోడించిన ప్రతి బిల్లు, జీతం, ప్లాన్ చేసిన కొనుగోలును లెక్కలోకి తీసుకుని, వచ్చే ఏడాదిలో మీ బ్యాలెన్స్ ఎప్పుడూ సున్నా కంటే తగ్గకుండా ఈ రోజు మీరు ఖర్చు చేయగల గరిష్ఠ మొత్తం ఇది.",
  "q4": "నా డేటా ఎక్కడ నిల్వ ఉంటుంది?",
  "a4": "మీ పరికరాల్లో, మీ సొంత iCloud ఖాతాలో — ఇదే మీ iPhone, iPad, Macలను సింక్‌లో ఉంచుతుంది. ఖాతాలు లేవు, సర్వర్లు లేవు, ట్రాకింగ్ లేదు. మేము మీ డేటాను చూడలేము.",
  "q5": "పన్నుల సంగతి ఏమిటి?",
  "a5": "ఏ ఆదాయానికైనా “పన్ను కోసం పక్కన పెట్టు” ఆన్ చేయండి, Future Cash పన్ను కోసం ఒక వాటాను పక్కన పెడుతుంది, కాబట్టి ఆ డబ్బు ఎప్పుడూ ఖర్చు చేయగలిగేదిగా లెక్కించబడదు. శాతాన్ని మీరు సెట్టింగ్‌లలో ఎంచుకోవచ్చు.",
